-- Rollback-only source authority and public-grant denials; no provider or remote capture.
begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
create function pg_temp.hosted_manifest()returns jsonb language sql immutable as $$select '{"version":"teacher-insight-1","purpose":"NEXT_LEARNING_ACTION","capabilities":["GROUNDED_EXPLANATION","RECOMMENDATION"],"mode":"FIXTURE","provider":"deterministic-fixture","model":"source-locked-v1","promptId":"next-learning-action","promptVersion":"1","promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077","promptSource":"SOURCE_CONTROLLED_TASK_POLICY","promptEffectiveAt":"2026-10-01T00:00:00Z","evaluationVersion":"source-78-checked-evidence-1","dataClassification":"SCHOOL_CUSTOM_NUMERIC","providerDataPolicy":"HOSTED_SYNTHETIC_FIXTURE","maxOutputTokens":1000,"timeoutMs":10000,"maxCost":1}'::jsonb$$;
grant execute on function pg_temp.hosted_manifest()to cuevo_api;
select ok(internal.valid_intelligence_execution_manifest(pg_temp.hosted_manifest()),'Hosted fixture keeps a truthful distinct manifest policy');
select ok(not internal.valid_intelligence_execution_manifest(pg_temp.hosted_manifest()||'{"mode":"LIVE"}'),'Hosted fixture authority never approves live execution');
select ok(not has_function_privilege('cuevo_api','internal.require_synthetic_intelligence_school(uuid)','EXECUTE'),'API cannot bypass private synthetic school precondition');
select ok(not has_function_privilege('cuevo_worker','internal.require_synthetic_intelligence_school(uuid)','EXECUTE'),'Worker cannot retrieve private school population');
select ok(not has_function_privilege('authenticated','internal.configure_posthog_school(uuid,boolean,text,integer)','EXECUTE'),'Data API cannot activate analytics');
select ok(not has_function_privilege('cuevo_api','internal.configure_posthog_school(uuid,boolean,text,integer)','EXECUTE'),'School API cannot impersonate analytics operator');
select ok(not has_table_privilege('cuevo_api','internal.intelligence_execution_bindings','SELECT,INSERT,UPDATE,DELETE'),'Execution approval stays function-only and immutable');
select throws_ok($$select internal.require_synthetic_intelligence_school(null)$$,'42501',null,'Unknown school does not become a synthetic population');
insert into app.schools(id,name,country_code)values('87000000-0000-4000-8000-000000000001','Rollback-only empty synthetic authority school','QA');
select throws_ok($$select internal.require_synthetic_intelligence_school('87000000-0000-4000-8000-000000000001')$$,'42501',null,'Empty school cannot receive synthetic intelligence authority');

select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into app.intelligence_policies(school_id,version,fixture_enabled,live_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',991,true,false,'20000000-0000-4000-8000-000000000001')on conflict(school_id)do update set version=991,fixture_enabled=true,live_enabled=false,data_classification='SCHOOL_CUSTOM_NUMERIC',allowed_actions=array['GUIDED_PRACTICE','REVIEW_FEEDBACK'];
select throws_ok($$select internal.require_intelligence_execution(pg_temp.hosted_manifest())$$,'22023',null,'Hosted fixture does not auto-register source-authorized local approval');
select is((select count(*)from internal.intelligence_execution_bindings where school_id='10000000-0000-4000-8000-000000000001'and policy_version=991),0::bigint,'Denied hosted execution creates no binding');
set local role cuevo_api;
select throws_ok($$select internal.approve_intelligence_execution(pg_temp.hosted_manifest(),'hosted-teacher-denied')$$,'42501',null,'Teacher cannot approve hosted execution');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select lives_ok($$select internal.approve_intelligence_execution(pg_temp.hosted_manifest(),'hosted-admin-approved')$$,'Admin explicitly approves current synthetic hosted execution');
reset role;
select is((select approval_source from internal.intelligence_execution_bindings where school_id='10000000-0000-4000-8000-000000000001'and policy_version=991),'EXPLICIT_SCHOOL_POLICY','Hosted binding has actual school approval provenance');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.require_intelligence_execution(pg_temp.hosted_manifest())$$,'Explicit hosted binding admits entirely synthetic current school');

create temporary table hosted_fixture(baseline_id uuid,reservation jsonb);
grant select,insert,update on hosted_fixture to cuevo_api;
set local role cuevo_api;
do $$declare course uuid;assessment uuid;submission uuid;mark uuid;result uuid;begin
 insert into app.courses(school_id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001',"authorization".actor_id(),'Hosted synthetic authority source','School authored','PUBLISHED')returning id into course;
 insert into app.assessments(school_id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001',course,"authorization".actor_id(),'Synthetic baseline','Teacher authored task',10)returning id into assessment;
 perform internal.link_assessment_reference(assessment,'61000000-0000-4000-8000-000000000001',1);
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
 insert into app.submissions(school_id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001',assessment,"authorization".actor_id(),'Synthetic source')returning id into submission;
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
 mark:=internal.mark_submission(submission,0,'Reviewed feedback',2,0,true);result:=internal.release_marking(mark,1,false);
 insert into hosted_fixture(baseline_id)values(result);
end$$;
create function pg_temp.hosted_settings()returns jsonb language sql stable as $$select jsonb_build_object('mode','FIXTURE','provider','deterministic-fixture','model','source-locked-v1','promptId','next-learning-action','promptVersion','1','promptDigest',pg_temp.hosted_manifest()->>'promptDigest','policyVersion',991,'timeoutMs',10000,'maxTokens',1000,'maxCost',1,'costBasis','DETERMINISTIC_FIXTURE','executionManifest',pg_temp.hosted_manifest())$$;
select lives_ok($$update hosted_fixture set reservation=internal.begin_teacher_insight_run('hosted-synthetic-run',repeat('a',64),baseline_id,pg_temp.hosted_settings(),'hosted-run')$$,'Explicit hosted synthetic source reserves the existing governed run');
reset role;
update app.people set synthetic=false where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000013';
select throws_ok($$select internal.require_intelligence_execution(pg_temp.hosted_manifest())$$,'42501',null,'Mixed school population denies already approved hosted binding');
set local role cuevo_api;
select throws_ok($$select internal.begin_teacher_insight_run('mixed-hosted-denied',repeat('b',64),(select baseline_id from hosted_fixture),pg_temp.hosted_settings(),'mixed-run')$$,'42501',null,'Mixed population denies hosted reservation even without syntheticOnly caller flag');
select throws_ok($$select internal.begin_teacher_insight_run('hosted-synthetic-run',repeat('a',64),(select baseline_id from hosted_fixture),pg_temp.hosted_settings(),'hosted-replay')$$,'42501',null,'Mixed population denies original-key fixture replay');
select throws_ok($$select internal.complete_intelligence_run((select(reservation->>'runId')::uuid from hosted_fixture),(select(reservation->>'leaseToken')::uuid from hosted_fixture),'{}','{}','hosted-complete')$$,'42501',null,'Mixed population is rechecked before fixture completion');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select throws_ok($$select internal.approve_intelligence_execution(pg_temp.hosted_manifest(),'mixed-approval')$$,'42501',null,'Mixed population denies fresh hosted execution approval');
select throws_ok($$select internal.approve_school_intelligence_policy('{"purpose":"NEXT_LEARNING_ACTION","dataClassification":"SCHOOL_CUSTOM_NUMERIC","fixtureEnabled":true,"liveEnabled":false,"allowedActions":["GUIDED_PRACTICE"],"expectedVersion":991,"confirmApproval":true,"reason":"Rollback-only synthetic policy denial"}','mixed-school-policy',repeat('c',64),'mixed-policy')$$,'42501',null,'Mixed population denies fixture school policy approval');
reset role;
select is((select count(*)from app.intelligence_runs where command_key='mixed-hosted-denied'),0::bigint,'Denied population creates no run');
update app.people set synthetic=true where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000013';

insert into app.school_policy_versions(school_id,version,reason,approved_by,analytics_enabled)values('10000000-0000-4000-8000-000000000001',991,'Rollback-only current school analytics approval','20000000-0000-4000-8000-000000000001',true);
set local app.runtime_env='synthetic-staging';
select throws_ok($$select internal.configure_posthog_school('10000000-0000-4000-8000-000000000001',true,'QA',991)$$,'22023',null,'Hosted operator cannot relabel staged capture as QA');
select ok(internal.configure_posthog_school('10000000-0000-4000-8000-000000000001',true,'STAGING',991),'Explicit hosted operator activation retains STAGING and fresh cutoff');
select ok(internal.posthog_school_allowed('10000000-0000-4000-8000-000000000001'),'Current approved populated synthetic school can be captured');
update app.people set synthetic=false where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000013';
select ok(not internal.posthog_school_allowed('10000000-0000-4000-8000-000000000001'),'Mixed school immediately loses capture authority');
select throws_ok($$select internal.configure_posthog_school('10000000-0000-4000-8000-000000000001',true,'STAGING',991)$$,'42501',null,'Mixed hosted school cannot activate capture');
set local app.runtime_env='production';
select throws_ok($$select internal.configure_posthog_school('10000000-0000-4000-8000-000000000001',true,'STAGING',991)$$,'22023',null,'Production label does not approve synthetic capture');
select *from finish();
rollback;
